import{_ as r,l,o as e,c as E,v as t,p as o,x as s,d as n,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"缺失分类","description":"","frontmatter":{"title":"缺失分类","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-miss-types.md","filePath":"cs/cache-miss-types.md","lastUpdated":1789023840000}'),h={name:"cs/cache-miss-types.md"};function p(d,a,B,C,m,_){const i=l("Mermaid");return e(),E("div",null,[a[1]||(a[1]=t('<h1 id="缺失分类" tabindex="-1">缺失分类 <a class="header-anchor" href="#缺失分类" aria-label="Permalink to &quot;缺失分类&quot;">​</a></h1><div class="epigraph"><p>一次缺失要么是第一次见到这块，要么是容量不够，要么是相联度把还能留下的块挤掉了。</p><footer>—— 据 Hill and Smith, Evaluating Associativity in CPU Caches, IEEE TC 1989；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/write-through">上一课</a>把写回与写分配钉成默认。标签、组、替换都已有。<a href="/cs/locality-principle">局部性原理</a>解释了为什么会命中，还没解释缺失从哪三类来。本课不重讲 LRU。缺口是：同样一次缺失，加大容量、提高相联度、加预取，药不同。本课只交出强制、容量、冲突三类，并把它们接回 CPI 的停顿项。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只报一个缺失率，无法决定下一步改硬件还是改程序。直接映射下「互踢」与「cache 太小」看起来一样。缺口不是新的映射函数，而是<strong>把缺失相对于一个理想全相联、无限大、再相对于同容量全相联来分类</strong>。</p><p>强制（冷）缺失：这块从未进过 cache，再大也逃不掉第一次。容量缺失：工作集比 cache 大，全相联同容量仍会缺。冲突缺失：同容量全相联不会缺，但有限相联度互踢。Hill 与 Smith 的这套三分是分析工具，不是运行时硬件打的标签。</p><p><span class="marginnote">有时加第四类一致性缺失：多核把块作废。本课仍在单核；那一类放到一致性课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对给定轨迹：无限 cache 仍发生的缺失是强制。再对有限容量 \\(C\\) 的全相联 LRU 计数，多出来的是容量。实际 \\(n\\) 路相对该全相联多出来的是冲突。预取可以减少强制（提前把块请来），增大 \\(C\\) 减少容量，提高 \\(n\\) 减少冲突。</p>',9)),(e(),o(A,null,{default:s(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E4%B8%80%E6%AC%A1%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20COMP%5B%22%E5%BC%BA%E5%88%B6%EF%BC%9A%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%A7%81%E8%AF%A5%E5%9D%97%22%5D%0A%20%20MISS%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%EF%BC%9A%E5%B7%A5%E4%BD%9C%E9%9B%86%E5%A4%A7%E4%BA%8E%20C%22%5D%0A%20%20MISS%20--%3E%20CONF%5B%22%E5%86%B2%E7%AA%81%EF%BC%9A%E7%9B%B8%E8%81%94%E5%BA%A6%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20COMP%20--%3E%20PRE%5B%22%E5%90%8E%E8%AF%BE%2F%E7%BC%96%E8%AF%91%EF%BC%9A%E9%A2%84%E5%8F%96%22%5D%0A%20%20CAP%20--%3E%20BIG%5B%22%E5%A2%9E%E5%A4%A7%E5%AE%B9%E9%87%8F%22%5D%0A%20%20CONF%20--%3E%20ASSOC%5B%22%E6%8F%90%E9%AB%98%E7%9B%B8%E8%81%94%E5%BA%A6%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>三类之和等于实测缺失次数（单核、无一致性失效时）。写缺失按是否分配计入同一轨迹。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分类把<a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>里的存储器停顿拆开：强制缺失率随问题规模降得慢；容量缺失率随 \\(C\\) 降；冲突在 2–8 路后通常饱和。设计者不该用加路去治容量病。</p><p>程序改布局（数组按行扫、减少冲突索引）主要打冲突与空间局部性，不增加 SRAM 面积。这是软件与硬件分担的同一项 CPI。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不测量具体基准，不引入 victim cache 作为第四种结构——它是减轻冲突的附录手段。也不把页缺失的「缺页」混进三类：页是下一课的粒度，尽管分析语言相似。</p><p>后课默认：谈到缺失，能说它更像强制、容量还是冲突。虚拟内存的缺页另计数，不并进 cache 的 CPI 项而不声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>强制 / 容量 / 冲突三分，相对于无限与同容量全相联定义。</li><li>加容量、加路、预取分别对三类。</li><li>分页把「块」换成「页」，是下一课的缺口。</li><li>出处：Hill and Smith, <em>IEEE Trans. Computers</em>, 1989；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=r(h,[["render",p]]);export{P as __pageData,f as default};
